/** Images for a page, optionally narrowed to one kind. */
export function getPageImages(
  page: string,
  kind?: PageImageKind,
): PageImage[] {
  const all = pageImages[page] ?? [];
  return kind ? all.filter((i) => i.kind === kind) : all;
}
